import{_ as e,c as a,o as r,a4 as s}from"./chunks/framework.DzOtv0XR.js";const u=JSON.parse('{"title":"WebAssembly - 通用跨编程语言字节码技术","description":"","frontmatter":{},"headers":[],"relativePath":"web/webassembly.md","filePath":"web/webassembly.md"}'),t={name:"web/webassembly.md"},o=s('<h1 id="webassembly-通用跨编程语言字节码技术" tabindex="-1">WebAssembly - 通用跨编程语言字节码技术 <a class="header-anchor" href="#webassembly-通用跨编程语言字节码技术" aria-label="Permalink to &quot;WebAssembly - 通用跨编程语言字节码技术&quot;">​</a></h1><h2 id="特点" tabindex="-1">特点 <a class="header-anchor" href="#特点" aria-label="Permalink to &quot;特点&quot;">​</a></h2><p><strong>中间表示</strong>： <strong>原生支持</strong>：相通底层内存模型 <strong>生态系统</strong>：高度兼容</p><p><a href="https://developer.ibm.com/technologies/web-development/articles/why-webassembly-and-rust-together-improve-nodejs-performance/" target="_blank" rel="noreferrer">Why using WebAssembly and Rust improves Node.js performance – IBM Developer</a></p><blockquote><p>只从 chrome 来说，因为 wasm 和 js 的字节码最后公用的 是同一个 优化编译器(turbo fan) 如果你的应用不是非常计算密集，加上js和 wasm 之间通信的额外消耗， 最后的性能可能和 js 写的应用差不多， 甚至比 js 版本还差</p></blockquote><blockquote><p>如果你只是写一个功能比较简单的应用练练手，直接用 rust-wasm 一整套工具链(wasm-pack, wasm-bindgen)应该可以比较快的完成目标，大概率你应该不会遇到 rust 语言的坑，所有权等。</p></blockquote><p><a href="https://ffmpegwasm.github.io/" target="_blank" rel="noreferrer">FFMPEG.WASM</a></p><p><a href="https://bytecodealliance.github.io/wamr.dev/" target="_blank" rel="noreferrer">WAMR - WebAssembly Micro Runtime</a></p><h2 id="性能" tabindex="-1">性能 <a class="header-anchor" href="#性能" aria-label="Permalink to &quot;性能&quot;">​</a></h2><p>不一定更快，比如转图，用 rust 又通过 FFI 调用 c，需要额外的适配处理</p><blockquote><p>wasm版的webp转码速度比纯rust或纯c的版本，慢了8-10倍</p></blockquote><h2 id="wasmedge" tabindex="-1">WasmEdge <a class="header-anchor" href="#wasmedge" aria-label="Permalink to &quot;WasmEdge&quot;">​</a></h2><p>体积、速度、安全优势，相比于 linux/Node QuickJS 小型、可嵌入，几个 C 文件，在任何环境运行</p><p><a href="https://www.freecodecamp.org/chinese/news/edge-cloud-microservices-with-wasmedge-and-rust/" target="_blank" rel="noreferrer">边缘云微服务——如何利用 WasmEdge 和 Rust 构建高性能和安全的应用程序</a></p><h2 id="rust-和-c" tabindex="-1">Rust 和 C <a class="header-anchor" href="#rust-和-c" aria-label="Permalink to &quot;Rust 和 C&quot;">​</a></h2><p>Rust 提供了更好的内存安全保证和现代化的语言特性，而 C 则有更成熟的生态系统和更广泛的使用基础。</p><h2 id="内存" tabindex="-1">内存 <a class="header-anchor" href="#内存" aria-label="Permalink to &quot;内存&quot;">​</a></h2><p>每个 Wasm 实例拥有自己的私有内存空间，它不是跨进程共享的。内存是局限于单个 JavaScript 上下文和 Wasm 模块实例的。</p>',18),l=[o];function n(c,i,b,m,h,d){return r(),a("div",null,l)}const _=e(t,[["render",n]]);export{u as __pageData,_ as default};
